   UPDATE /* delBlockReactionAlims */
          TB_ALIMXX A
LEFT JOIN TB_REPLXX R
       ON R.REPL_NUMB = A.REPL_NUMB
      SET A.DELT_YSNO = #{commYes}
    WHERE A.USER_NUMB = #{userNumb}
      AND R.USER_NUMB = #{blocNumb}
      AND A.TEMP_CODE IN (#{replyReport}, #{replyProfile}, #{replyBackground}, #{replyToComment})
      AND A.TAGT_TYPE IN (#{targetReport}, #{targetProfile}, #{targetBackground})
      AND NOT EXISTS (
          SELECT 1 FROM TM_REPORT REPORT JOIN TB_CLPART PART ON PART.REPT_NUMB = REPORT.REPT_NUMB
           WHERE A.TAGT_TYPE = #{targetReport} AND REPORT.REPT_NUMB = A.TAGT_NUMB
             AND REPORT.PUBC_YSNO = #{commNo}
      )

