/* setBlock */
INSERT INTO TB_USBLOC (
            USER_NUMB
          , BLOC_NUMB
          , REGI_DATE
) VALUES (  #{userNumb}
          , #{blocNumb}
          , CURRENT_TIMESTAMP(6)
) AS NEW
ON DUPLICATE KEY UPDATE
       USER_NUMB = NEW.USER_NUMB

